<script setup lang="ts">
import { useI18n } from "../../../../../ribiwebgui/src/i18n/index";
import { computed, ref, watch } from "vue";
import { computerAnnotationShapeSchema } from "@shared/agentInteractiveProtocol";
import { browserUuid } from "../../../../../ribiwebgui/src/browserUuid";
import { drawingObject, drawingPoint, type DrawingObject, type DrawingPoint } from "./computerControlDrawing";
const { t } = useI18n();
const props=defineProps<{ image:Record<string,unknown>; disabled?:boolean; dynamicEnabled:boolean; trackingSupported?:boolean; durationMs?:unknown; backend?:unknown; rateHz?:unknown; busy?:boolean }>();
const emit=defineEmits<{show:[Record<string,unknown>];track:[Record<string,unknown>];}>();
const shapeSchema=computerAnnotationShapeSchema as {properties:{type:{enum:string[]};style:{properties:Record<string,{minimum?:number;maximum?:number}>}}};
const shape=ref(shapeSchema.properties.type.enum[0] || "");const objects=ref<DrawingObject[]>([]);const text=ref("");const drawing=ref(false);const style=ref<Record<string,unknown>>({});const expiry=ref("");const taskId=ref("");const layerId=ref(browserUuid());
const width=computed(()=>Number(props.image.width));const height=computed(()=>Number(props.image.height));const url=computed(()=>`data:${props.image.mimeType};base64,${props.image.data}`);
const labels:Record<string,string>={rect:"框",ellipse:"圈",arrow:"箭头",path:"路径",text:"文字",highlight:"高亮"};
let pointerId:number|undefined;let points:DrawingPoint[]=[];const preview=ref<DrawingObject>();
function point(event:PointerEvent){return drawingPoint(event.clientX,event.clientY,(event.currentTarget as SVGElement).getBoundingClientRect(),width.value,height.value);}
function start(event:PointerEvent){if(!drawing.value || props.disabled || !props.image.source)return;pointerId=event.pointerId;points=[point(event)];(event.currentTarget as Element).setPointerCapture(pointerId);preview.value=drawingObject(browserUuid(),shape.value,points,text.value,style.value);}
function move(event:PointerEvent){if(pointerId!==event.pointerId)return;points.push(point(event));preview.value=drawingObject(preview.value!.id,shape.value,points,text.value,style.value);}
function finish(event:PointerEvent){if(pointerId!==event.pointerId)return;move(event);if(preview.value)objects.value.push(preview.value);preview.value=undefined;pointerId=undefined;const element=event.currentTarget as Element;if(element.hasPointerCapture(event.pointerId))element.releasePointerCapture(event.pointerId);}
function cancel(){pointerId=undefined;preview.value=undefined;points=[];}
function show(){emit("show",{action:"annotation.show",layerId:layerId.value,source:props.image.source,objects:objects.value,durationMs:props.durationMs});}
function track(){emit("track",{action:"annotation.track.start",layerId:layerId.value,source:props.image.source,targets:objects.value.filter(object=>object.bounds),backend:props.backend,rateHz:props.rateHz,taskId:taskId.value,expiresAt:expiry.value?new Date(expiry.value).toISOString():null});}
watch(()=>props.image.source,()=>{objects.value=[];cancel();layerId.value=browserUuid();});
</script>
<template><section class="computer-canvas"><div class="canvas-toolbar"><v-switch v-model="drawing" :label="t('在画面上准备标注')" :disabled="disabled || !image.source" hide-details density="compact" /><v-select v-model="shape" :items="shapeSchema.properties.type.enum.map(value=>({title:t(labels[value] || value),value}))" :label="t('图形')" density="compact" hide-details /><v-text-field v-if="shape === 'text'" v-model="text" :label="t('文字')" density="compact" hide-details /><v-text-field :model-value="style.color" :label="t('颜色（可选）')" density="compact" hide-details @update:model-value="style.color=$event" /><v-text-field :model-value="style.lineWidth" :label="t('线宽（可选）')" type="number" :min="shapeSchema.properties.style.properties.lineWidth.minimum" density="compact" hide-details @update:model-value="style.lineWidth=Number($event)" /><v-text-field :model-value="style.fontSize" :label="t('字号（可选）')" type="number" density="compact" hide-details @update:model-value="style.fontSize=Number($event)" /><v-text-field :model-value="style.opacity" :label="t('透明度（可选）')" type="number" :min="shapeSchema.properties.style.properties.opacity.minimum" :max="shapeSchema.properties.style.properties.opacity.maximum" density="compact" hide-details @update:model-value="style.opacity=Number($event)" /></div>
<div class="canvas-image"><img :src="url" :alt="t('当前电脑画面')" draggable="false" /><svg :viewBox="`0 0 ${width} ${height}`" :class="{drawing}" role="img" :aria-label="t('标注预览，不向电脑注入输入')" @pointerdown="start" @pointermove="move" @pointerup="finish" @pointercancel="cancel" @lostpointercapture="cancel"><defs><marker :id="`arrow-${layerId}`" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="currentColor" /></marker></defs><g v-for="object in [...objects,...(preview?[preview]:[])]" :key="object.id" :stroke="String(object.style?.color || 'currentColor')" :stroke-width="object.style?.lineWidth as number|undefined" :opacity="object.style?.opacity as number|undefined" fill="none"><ellipse v-if="object.type === 'ellipse' && object.bounds" :cx="object.bounds.x+object.bounds.width/2" :cy="object.bounds.y+object.bounds.height/2" :rx="object.bounds.width/2" :ry="object.bounds.height/2" /><polyline v-else-if="object.type === 'arrow' || object.type === 'path'" :points="object.points?.map(point=>`${point.x},${point.y}`).join(' ')" :marker-end="object.type === 'arrow' ? `url(#arrow-${layerId})` : undefined" /><text v-else-if="object.type === 'text' && object.bounds" :x="object.bounds.x" :y="object.bounds.y" :font-size="object.style?.fontSize as number|undefined" :fill="String(object.style?.color || 'currentColor')" stroke="none">{{ object.text }}</text><rect v-else-if="object.bounds" :x="object.bounds.x" :y="object.bounds.y" :width="object.bounds.width" :height="object.bounds.height" :fill="object.type === 'highlight' ? String(object.style?.color || 'currentColor') : 'none'" /></g></svg></div><p class="canvas-note">{{ t('当前为待提交预览；只有目标电脑返回显示回执才表示原生标注已显示。') }}{{ objects.length }}{{ t(' 个图形。') }}</p>
<div class="canvas-actions"><v-btn :disabled="!objects.length || disabled" :loading="busy" variant="tonal" @click="show">{{ t('在电脑显示静态标注') }}</v-btn><v-btn :disabled="!objects.length" variant="text" @click="objects=[]">{{ t('清空本次草稿') }}</v-btn></div><details><summary>{{ t('持续跟踪这些目标') }}</summary><p class="canvas-note">{{ t('动态标注') }}{{ dynamicEnabled ? t('已开启') : t('未开启；请在设置中开启') }}{{ t('。使用已保存的跟踪方法和预算，持续处理会增加 CPU 占用。') }}</p><div class="canvas-toolbar"><v-text-field v-model="taskId" :label="t('所属任务标识')" :hint="t('跟随原任务生命周期，不因收起页面结束')" persistent-hint density="compact" /><v-text-field v-model="expiry" :label="t('到期时间（可选）')" type="datetime-local" density="compact" /><v-btn :disabled="disabled || !dynamicEnabled || !trackingSupported || !objects.some(object=>object.bounds) || !taskId" :loading="busy" variant="tonal" @click="track">{{ t('开始跟踪') }}</v-btn></div></details></section></template>
<style scoped>.computer-canvas{min-width:0;display:grid;gap:12px;}.canvas-toolbar{display:flex;align-items:start;flex-wrap:wrap;gap:10px;}.canvas-toolbar>*{min-width:140px;flex:1;}.canvas-image{position:relative;line-height:0;max-width:100%;}.canvas-image img{display:block;max-width:100%;height:auto;}.canvas-image svg{position:absolute;inset:0;width:100%;height:100%;color:var(--rr-accent-strong);pointer-events:none;}.canvas-image svg.drawing{pointer-events:auto;touch-action:none;cursor:crosshair;}.canvas-note{color:var(--rr-muted);font-size:.8rem;line-height:1.6;}.canvas-actions{display:flex;gap:8px;flex-wrap:wrap;}summary{cursor:pointer;padding:8px 0;}</style>
